export function GroupedList({
  heading = "{{heading}}",
  style = "{{style}}",
  accent = "{{accent}}",
  showCounts = {{showCounts}},
  itemGap = {{itemGap}},
}) {
  const groupStyle = {
    ...(style === "bordered" ? { border: "1px solid #24143020", borderRadius: 10, padding: "10px 12px" } : {}),
    ...(style === "card" ? { background: "#fff", borderRadius: 10, padding: "10px 12px", boxShadow: "0 2px 8px rgba(36,20,48,.08)" } : {}),
  };
  const groups = [
    { id: "todo", label: "To do", count: 2, items: ["Draft the proposal", "Review budget"] },
    { id: "done", label: "Done", count: 1, items: ["Kickoff call"] },
  ];
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2", maxWidth: 320, width: 320, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      {groups.map((g, i) => (
        <div key={g.id} style={{ ...groupStyle, marginTop: i === 0 ? 0 : itemGap }}>
          <h4 id={`rgl-${g.id}`} style={{ margin: "0 0 6px", fontSize: 12, fontWeight: 700, color: accent, textTransform: "uppercase", letterSpacing: ".03em" }}>
            {g.label}{showCounts && <span style={{ marginLeft: 6, background: accent, color: "#241430", borderRadius: 10, padding: "1px 7px", fontSize: 11, fontWeight: 700 }}>{g.count}</span>}
          </h4>
          <ul aria-labelledby={`rgl-${g.id}`} style={{ listStyle: "none", margin: 0, padding: 0 }}>
            {g.items.map((item) => <li key={item} style={{ padding: "7px 2px" }}>{item}</li>)}
          </ul>
        </div>
      ))}
    </section>
  );
}
